def parse_row(line: str) -> list[str]:
    fields = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            # Check if this quote is escaped by another quote (two consecutive quotes)
            if len(current_field) > 0 and current_field[-1] == '"' and not in_quotes:
                current_field += '"'
            else:
                in_quotes = not in_quotes
        elif char == ',' and not in_quotes:
            fields.append(current_field.strip())
            current_field = ""
        else:
            current_field += char

    # Append the last field if there is any remaining content
    if current_field or line.endswith(','):
        fields.append(current_field.strip())

    return fields
